CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"6f0d1e6c-b8cc-5770-8547-9f561a5c71f7","source_id":"0873","name_en":"cable reverse crunch","name_ar":"\u0623\u0632\u0645\u0629 \u0627\u0644\u0643\u0627\u0628\u0644 \u0627\u0644\u0639\u0643\u0633\u064a","match_names":["cable reverse crunch"],"muscle":"core","equipment":"cable","aliases":["cable reverse crunch"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a cable to a low pulley and lie down facing up on a mat.\nHold the cable with both hands and extend your arms straight up towards the ceiling.\nBend your knees and lift your legs up, bringing your thighs towards your chest.\nWhile keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.\nPause for a moment at the top, then slowly lower your hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0643\u0627\u0628\u0644 \u0628\u0628\u0643\u0631\u0629 \u0645\u0646\u062e\u0641\u0636\u0629 \u0648\u0627\u0633\u062a\u0644\u0642\u0650 \u0639\u0644\u0649 \u0627\u0644\u0633\u062c\u0627\u062f\u0629 \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u062c\u0644\u0628 \u0641\u062e\u0630\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0631\u0627\u0631 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643\u060c \u0642\u0645 \u0628\u062b\u0646\u064a \u062d\u0648\u0636\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0631\u0641\u0639 \u0648\u0631\u0643\u064a\u0643 \u0639\u0646 \u0627\u0644\u0633\u062c\u0627\u062f\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0648\u0631\u0643\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0873","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0873-RqOtqD7.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0873-RqOtqD7.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"25520b4f-b9c2-58a2-8ffd-ad30031b8c7f","source_id":"0206","name_en":"cable reverse curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u0643\u0627\u0628\u0644 \u0627\u0644\u0639\u0643\u0633\u064a","match_names":["cable reverse curl"],"muscle":"biceps","equipment":"cable","aliases":["cable reverse curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a straight bar to a low pulley cable machine.\nStand facing the machine with your feet shoulder-width apart and your knees slightly bent.\nGrasp the bar with an underhand grip, hands shoulder-width apart.\nKeep your elbows close to your sides and your upper arms stationary throughout the exercise.\nExhale and curl the bar up towards your shoulders, contracting your biceps.\nPause for a moment at the top, squeezing your biceps.\nInhale and slowly lower the bar back to the starting position, fully extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0634\u0631\u064a\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0628\u0622\u0644\u0629 \u0643\u0627\u0628\u0644 \u0630\u0627\u062a \u0628\u0643\u0631\u0629 \u0645\u0646\u062e\u0641\u0636\u0629.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0628\u0627\u0631 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0628\u0627\u0631 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643\u060c \u0645\u0639 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u0628\u0627\u0631 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0206","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0206-eOG0r6v.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0206-eOG0r6v.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e1f0b958-2613-5ab1-84db-7bfea7ff8623","source_id":"2406","name_en":"cable reverse grip triceps pushdown (sz-bar) (with arm blaster)","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0628\u0642\u0628\u0636\u0629 \u0639\u0643\u0633\u064a\u0629 (SZ-Bar) (\u0645\u0639 \u0645\u0643\u0628\u0631 \u0627\u0644\u0630\u0631\u0627\u0639)","match_names":["cable reverse grip triceps pushdown (sz-bar) (with arm blaster)"],"muscle":"triceps","equipment":"cable","aliases":["cable reverse grip triceps pushdown (sz-bar) (with arm blaster)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a straight bar to the cable machine at the highest setting.\nStand facing the cable machine with your feet shoulder-width apart.\nGrasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.\nKeep your elbows close to your sides and your upper arms stationary throughout the exercise.\nEngage your triceps and slowly push the bar down until your arms are fully extended.\nPause for a moment at the bottom, then slowly return the bar to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0634\u0631\u064a\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0628\u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0623\u0639\u0644\u0649 \u0625\u0639\u062f\u0627\u062f.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0628\u0627\u0631 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a 