42 \u0633\u062d\u0628 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0648\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0642\u0628\u0627\u0636 \u0627\u0644\u0643\u0627\u0645\u0644\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0628\u0628\u0637\u0621 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1321","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1321-c8oybX6.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1321-c8oybX6.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d5ff5526-0cc9-5914-8e0a-e7782217dd7d","source_id":"1322","name_en":"cable rope extension incline bench row","name_ar":"\u062a\u0645\u062f\u064a\u062f \u062d\u0628\u0644 \u0627\u0644\u0643\u0627\u0628\u0644 \u0627\u0646\u062d\u062f\u0631 \u0635\u0641 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621","match_names":["cable rope extension incline bench row"],"muscle":"back","equipment":"cable","aliases":["cable rope extension incline bench row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.\nAttach a rope handle to the cable machine and sit on the incline bench facing the machine.\nGrab the rope handle with an overhand grip and lean forward, keeping your back straight.\nExtend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.\nSqueeze your shoulder blades together at the end of the movement.\nSlowly release the tension and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629 \u0648\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0622\u0644\u0629 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0627\u0644\u0628\u0643\u0631\u0629 \u0627\u0644\u0645\u0646\u062e\u0641\u0636\u0629.\n\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0642\u0628\u0636 \u062d\u0628\u0644 \u0628\u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0648\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0627\u0626\u0644 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629.\n\u0623\u0645\u0633\u0643 \u0628\u0645\u0642\u0628\u0636 \u0627\u0644\u062d\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629 \u0648\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0627\u0633\u062d\u0628 \u0627\u0644\u062d\u0628\u0644 \u0646\u062d\u0648 \u0623\u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0648\u062a\u0631 \u0628\u0628\u0637\u0621 \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1322","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1322-MgKwAAo.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1322-MgKwAAo.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"fe5baa39-1263-500f-829d-292699328d5b","source_id":"1639","name_en":"cable rope hammer preacher curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0645\u0637\u0631\u0642\u0629 \u062d\u0628\u0644 \u0627\u0644\u0643\u0627\u0628\u0644","match_names":["cable rope hammer preacher curl"],"muscle":"biceps","equipment":"cable","aliases":["cable rope hammer preacher curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a rope attachment to a low pulley cable machine.\nStand facing the machine with your feet shoulder-width apart.\nGrasp the rope with a neutral grip (palms facing each other).\nPosition your upper arms against the preacher bench pad, keeping your elbows slightly bent.\nKeeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly lower the rope back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0631\u0641\u0642 \u062d\u0628\u0644 \u0628\u0622\u0644\u0629 \u0643\u0627\u0628\u0644 \u0630\u0627\u062a \u0628\u0643\u0631\u0629 \u0645\u0646\u062e\u0641\u0636\u0629.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u0645\u062d\u0627\u064a\u062f\u0629 (\u0643\u0641 \u0627\u0644\u064a\u062f \u062a\u0648\u0627\u062c\u0647 \u0628\u0639\u0636\u0647\u0627 \u0627\u0644\u0628\u0639\u0636).\n\u0636\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u0639\u0644\u0649 \u0648\u0633\u0627\u062f\u0629 \u0645\u0642\u0639\u062f \u0627\u0644\u0648\u0627\u0639\u0638\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u062d\u0628\u0644 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0646\u0634\u0642 \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1639","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1639-PcPe0P5.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1639-PcPe0P5.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9c5b510f-e62e-5ff7-86ac-cf4e44e8bb4d","source_id":"1724","name_en":"cable rope high pulley overhead tricep extension","name_ar":"\u062d\u0628\u0644 \u0643\u0627\u0628\u0644\u060c \u0628\u0643\u0631\u0629 \u0639\u0627\u0644\u064a\u0629\u060c \u0627\u0645\u062a\u062f\u0627\u062f \u0644\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633","match_names":["cable rope high pulley overhead tricep extension"],"muscle":"triceps","equipment":"cable","aliases":["cable rope high pulley overhead tricep extension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a rope to a high pulley and adjust the weight accordingly.\nStand facing away from the pulley machine with your feet shoulder-width apart.\nGrasp the rope with both hands, palms facing down, and bring your hands above your head.\nKeep your upper arms close to your head and perpendicular to the floor.\nSlowly lower the rope behind your head by bending your elbows.\nPause for a moment, then extend your arms back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0628\u0637 \u062d\u0628\u0644\u064b\u0627 \u0628\u0628\u0643\u0631\u0629 \u0639\u0627\u0644\u064a\u0629 \u0648\u0627\u0636\u0628\u0637 \u0627\u0644\u0648\u0632\u0646 \u0648\u0641\u0642\u064b\u0627 \u0644\u0630\u0644\u0643.\n\u0642\u0641 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0622\u0644\u0629 \u0627\u0644\u0628\u0643\u0631\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u064a\u062f\u064a\u0643 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0648\u0645\u062a\u0639\u0627\u0645\u062f\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u0628\u0644 \u0628\u0628\u0637\u0621 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1724","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1724-NN8nSNT.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1724-NN8nSNT.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2d6f1e41-7315-5348-89a7-bf6144c01be8","source_id":"1725","name_en":"cable rope incline tricep extension","name_ar":"\u062d\u0628\u0644 \u0627\u0644\u0643\u0627\u0628\u0644 \u0645\u0646\u062d\u062f\u0631 \u0644\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633","match_names":["cable rope incline tricep extension"],"muscle":"triceps","equipment":"cable","aliases":["cable rope incline tricep extension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.\nStand facing away from the pulley with your feet shoulder-width apart.\nGrasp the rope with an overhand grip and extend your arms straight overhead.\nKeep your elbows close to your head and your upper arms stationary throughout the exercise.\nLower the rope behind your head by bending your elbows until your forearms touch your biceps.\nPause for a moment, then extend your arms back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0628\u0637 \u062d\u0628\u0644\u064b\u0627 \u0628\u0628\u0643\u0631\u0629 \u0639\u0627\u0644\u064a\u0629 \u0648\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0627\u0626\u0644 \u0639\u0644\u0649 \u0632\u0627\u0648\u064a\u0629 \u0645\u0631\u064a\u062d\u0629.\n\u0642\u0641 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u0628\u0643\u0631\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062d\u0628\u0644 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u062a\u0649 \u062a\u0644\u0645\u0633 \u0633\u0627\u0639\u062f\u0627\u0643 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1725","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1725-ZujAdR9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1725-ZujAdR9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner