2\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0628\u0642\u0650 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0645\u0646\u0634\u063a\u0644\u0629\u060c \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0627\u0636\u063a\u0637 \u0628\u062c\u0630\u0639\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u064a\u0643\u060c \u0648\u062c\u0644\u0628 \u0645\u0631\u0641\u0642\u064a\u0643 \u0646\u062d\u0648 \u0641\u062e\u0630\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0627\u062a \u0623\u0633\u0641\u0644 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0226","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0226-jpgqxiS.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0226-jpgqxiS.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c31b7812-9fe8-54ee-869c-837f57e2b4d6","source_id":"0874","name_en":"cable standing crunch (with rope attachment)","name_ar":"\u0623\u0632\u0645\u0629 \u0627\