a\u0643 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0637\u062d\u0646\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0874","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0874-XU3ePuv.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0874-XU3ePuv.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8170c07a-6fe9-54f9-861b-b4b764ea38ee","source_id":"0227","name_en":"cable standing fly","name_ar":"\u0643\u0627\u0628\u0644 \u064a\u0642\u0641 \u064a\u0637\u064a\u0631","match_names":["cable standing fly"],"muscle":"chest","equipment":"cable","aliases":["cable standing fly"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the handles to the cables at chest height.\nStand with your feet shoulder-width apart, facing away from the cable machine.\nGrasp the handles with an overhand grip, palms facing forward.\nStep forward slightly to create tension in the cables.\nKeep your core engaged and your back straight throughout the exercise.\nWith a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.\nSqueeze your chest muscles at the peak of the movement.\nSlowly reverse the movement, returning your arms to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0635\u062f\u0631.\n\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0648\u062c\u0647\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u062a\u0642\u062f\u0645 \u0644\u0644\u0623\u0645\u0627\u0645 \u0642\u0644\u064a\u0644\u064b\u0627 \u0644\u062e\u0644\u0642 \u062a\u0648\u062a\u0631 \u0641\u064a \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0646\u0634\u063a\u0627\u0644 \u0642\u0644\u0628\u0643 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0645\u0639 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b\u060c \u0627\u0633\u062d\u0628 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0648\u0636\u0645\u0647\u0645\u0627 \u0645\u0639\u064b\u0627 \u0623\u0645\u0627\u0645 \u0635\u062f\u0631\u0643.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643 \u0641\u064a \u0630\u0631\u0648\u0629 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0642\u0645 \u0628\u0639\u0643\u0633 \u0627\u0644\u062d\u0631\u0643\u0629 \u0628\u0628\u0637\u0621\u060c \u0645\u0639 \u0625\u0639\u0627\u062f\u0629 \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0227","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["deltoids","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0227-Pr9Rhf4.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0227-Pr9Rhf4.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"781b36e5-cd41-51a8-8746-d7219a7cf337","source_id":"0228","name_en":"cable standing hip extension","name_ar":"\u0643\u0627\u0628\u0644 \u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643 \u0627\u0644\u062f\u0627\u0626\u0645\u0629","match_names":["cable standing hip extension"],"muscle":"glutes","equipment":"cable","aliases":["cable standing hip extension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a cable to a low pulley and stand facing away from the machine.\nPlace the cable around your ankle and stand with your feet shoulder-width apart.\nKeep your core engaged and your back straight throughout the exercise.\nSlowly extend your leg straight back, squeezing your glutes at the top of the movement.\nPause for a moment, then return to the starting position.\nRepeat for the desired number of repetitions.\nSwitch sides and repeat with the other leg.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0643\u0627\u0628\u0644 \u0628\u0628\u0643\u0631\u0629 \u0645\u0646\u062e\u0641\u0636\u0629 \u0648\u0627\u0642\u0641 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629.\n\u0636\u0639 \u0627\u0644\u0643\u0627\u0628\u0644 \u062d\u0648\u0644 \u0643\u0627\u062d\u0644\u0643 \u0648\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0646\u0634\u063a\u0627\u0644 \u0642\u0644\u0628\u0643 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0623\u0631\u062f\u0627\u0641 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.\n\u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0228","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0228-Kpajagk.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0228-Kpajagk.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4acfc48b-c77a-5d58-8d82-f2eb7782cb29","source_id":"0229","name_en":"cable standing inner curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u062f\u0627\u062e\u0644\u064a\u0629 \u0644\u0644\u0643\u0627\u0628\u0644","match_names":["cable standing inner curl"],"muscle":"biceps","equipment":"cable","aliases":["cable standing inner curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand facing a cable machine with your feet shoulder-width apart.\nGrasp the cable handle with an underhand grip, palms facing up.\nKeep your elbows close to your sides and your upper arms stationary.\nExhale and curl the cable handle towards your shoulders, contracting your biceps.\nPause for a moment at the top of the movement, squeezing your biceps.\nInhale and slowly lower the cable handle back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0623\u0639\u0644\u0649.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646.\n\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0642\u0645 \u0628\u0644\u0641 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643\u060c \u0645\u0645\u0627 \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0646\u0634\u0642 \u0648\u0627\u062e\u0641\u0636 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u06