epeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0636\u0639\u0647 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u062e\u0635\u0631.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0638\u0647\u0631 \u0645\u0633\u062a\u0642\u064a\u0645 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0627\u0631\u0641\u0639 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0644\u060c \u0645\u0639 \u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u06